.mpa{--a-ink:var(--wf-color-text,#202326);--a-muted:var(--wf-color-muted,#62676c);--a-line:var(--wf-color-border,#e2e4e6);--a-paper:var(--wf-color-surface,#fff);--a-soft:var(--wf-color-secondary,#f5f6f7);--a-accent:var(--wf-color-accent,#ff9800);color:var(--a-ink);font:16px/1.65 var(--wf-font-body,Inter,Arial,sans-serif);padding-bottom:72px;background:var(--a-paper)}.mpa *{box-sizing:border-box}.mpa [hidden]{display:none!important}.mpa a{color:inherit;text-decoration:none}.mpa h1,.mpa h2,.mpa h3,.mpa p,.mpa figure{margin:0}.mpa h1,.mpa h2,.mpa h3{line-height:1.12;letter-spacing:-.035em}.mpa h1{font-size:clamp(38px,4.5vw,60px);font-weight:800}.mpa h2{font-size:clamp(28px,3vw,40px);font-weight:780}.mpa h3{font-size:23px;font-weight:750}.mpa img{display:block;max-width:100%;object-fit:cover}.mpa :focus-visible{outline:3px solid #a75d00;outline-offset:4px}.mpa section[id]{scroll-margin-top:110px}.mpa-wrap{width:min(1280px,calc(100% - 48px));margin-inline:auto}.mpa-crumb{display:flex;gap:10px;color:var(--a-muted);font-size:12px;padding:28px 0}.mpa-crumb a:hover{text-decoration:underline}.mpa-kicker{display:flex;gap:10px;align-items:center;color:var(--a-muted);font-size:11px;font-weight:750;letter-spacing:.13em;text-transform:uppercase;margin-bottom:22px}.mpa-kicker:before{content:"";width:28px;height:3px;background:var(--a-accent)}.mpa-lead{font-size:18px;color:var(--a-muted);line-height:1.7;margin-top:24px!important;max-width:570px}.mpa-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.mpa-btn{display:inline-flex;align-items:center;justify-content:center;gap:20px;min-height:46px;padding:12px 21px;border:1px solid transparent;border-radius:7px;font-size:14px;font-weight:750;background:var(--a-accent);color:#202326!important}.mpa-btn:hover{filter:brightness(.96)}.mpa-btn-outline{background:var(--a-paper);border-color:var(--a-line);color:var(--a-ink)!important}.mpa-text-link{display:inline-flex;align-items:center;gap:14px;font-size:14px;font-weight:700;text-decoration:underline!important;text-underline-offset:4px}.mpa-hero{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;padding:25px 0 52px}.mpa-hero-visual{position:relative;min-width:0}.mpa-hero-visual>img{width:100%;height:450px;border-radius:12px}.mpa-visual-note{display:flex;align-items:center;gap:15px;padding:17px 21px;border:1px solid var(--a-line);border-radius:8px;background:var(--a-paper);position:absolute;left:22px;right:22px;bottom:22px;font-size:13px;font-weight:650;line-height:1.5}.mpa-visual-note>span{display:block;width:3px;height:30px;background:var(--a-accent);flex:none}.mpa-proof{display:grid;grid-template-columns:.65fr .65fr 1.7fr;gap:0;border-top:1px solid var(--a-line);border-bottom:1px solid var(--a-line);padding:28px 0}.mpa-proof>div{padding:0 30px;border-left:1px solid var(--a-line)}.mpa-proof>div:first-child{padding-left:0;border:0}.mpa-proof strong{display:block;font-size:34px;letter-spacing:-.04em;line-height:1.1}.mpa-proof span{display:block;font-size:13px;color:var(--a-muted);margin-top:8px}.mpa-proof .mpa-proof-copy strong{font-size:22px;line-height:1.25;letter-spacing:-.025em;max-width:500px}.mpa-section{padding-top:72px}.mpa-heading{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:end;margin-bottom:35px}.mpa-heading p{color:var(--a-muted);font-size:16px;max-width:550px}.mpa-values{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:40px}.mpa-value{border-top:1px solid var(--a-line);padding-top:25px}.mpa-no{font-size:12px;color:var(--a-muted);font-weight:700;display:block;margin-bottom:22px}.mpa-value h3{font-size:23px;max-width:320px}.mpa-value p{color:var(--a-muted);font-size:15px;margin-top:16px}.mpa-story{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;padding-top:72px}.mpa-story img{width:100%;height:400px;border-radius:12px}.mpa-story p{margin-top:22px;color:var(--a-muted);font-size:16px}.mpa-bullets{list-style:none;padding:0;margin:24px 0 0}.mpa-bullets li{display:flex;gap:12px;margin:12px 0;color:var(--a-muted);font-size:15px}.mpa-bullets li:before{content:"✓";color:#a75d00;font-weight:800;flex:none}.mpa-reference-row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:30px}.mpa-reference{overflow:hidden;border-radius:10px;border:1px solid var(--a-line)}.mpa-reference-image{overflow:hidden;aspect-ratio:4/3;background:var(--a-soft)}.mpa-reference img{height:100%;width:100%;transition:transform .3s}.mpa-reference:hover img{transform:scale(1.025)}.mpa-reference-copy{padding:22px}.mpa-reference-copy p{color:var(--a-muted);font-size:10px;letter-spacing:.075em;text-transform:uppercase;margin-bottom:8px}.mpa-reference-copy h3{font-size:21px}.mpa-reference-copy>span{display:block;font-size:12px;font-weight:700;margin-top:18px}.mpa-cta{display:flex;gap:35px;justify-content:space-between;align-items:center;margin-top:72px;background:#fff5e6;border:1px solid #f4dfc2;border-radius:12px;padding:38px 40px}.mpa-cta h2{font-size:30px;max-width:750px}.mpa-cta p{font-size:15px;color:var(--a-muted);margin-top:12px}.mpa-cta .mpa-btn{flex:none}.mpa-jumps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}.mpa-jumps a{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 20px;border:1px solid var(--a-line);border-radius:8px;font-weight:650;font-size:14px;background:var(--a-paper)}.mpa-jumps a:hover{border-color:#e7ba78;background:#fff8ed}.mpa-jumps span{color:var(--a-muted);font-size:12px}.mpa-install{display:grid;grid-template-columns:1fr 1fr;gap:64px;border-top:1px solid var(--a-line);padding-top:50px;margin-top:35px;align-items:start}.mpa-install p{font-size:16px;color:var(--a-muted);margin-top:20px}.mpa-types{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:0 24px;padding:0;margin:0}.mpa-types li{border-bottom:1px solid var(--a-line);padding:13px 0;font-size:14px;display:flex;gap:12px;align-items:center}.mpa-types li:before{content:"";width:5px;height:5px;background:var(--a-accent);flex:none}.mpa-service{display:grid;grid-template-columns:.95fr 1.05fr;gap:64px;align-items:center;padding-top:64px}.mpa-service img{width:100%;height:360px;border-radius:12px}.mpa-service-copy p{color:var(--a-muted);font-size:16px;margin-top:22px}.mpa-service-copy .mpa-text-link{margin-top:26px}.mpa-service-reverse .mpa-service-image{order:2}.mpa-service-reverse .mpa-service-copy{order:1}.mpa-image-square img{object-position:center}.mpa-process{border-top:1px solid var(--a-line);padding-top:48px;margin-top:72px}.mpa-faq{display:grid;grid-template-columns:.8fr 1.2fr;gap:80px;margin-top:72px;border-top:1px solid var(--a-line);padding-top:48px}.mpa-faq p{color:var(--a-muted);margin-top:18px;font-size:15px}.mpa-faq details{border-bottom:1px solid var(--a-line)}.mpa-faq summary{list-style:none;cursor:pointer;padding:19px 35px 19px 0;font-weight:650;font-size:16px;position:relative}.mpa-faq summary::-webkit-details-marker{display:none}.mpa-faq summary:after{content:"+";position:absolute;right:4px;top:13px;font-size:26px;font-weight:400;color:var(--a-muted)}.mpa-faq details[open] summary:after{content:"−"}.mpa-faq details p{font-size:14px;margin:0 28px 23px 0;line-height:1.75}.mpa-caption{font-size:12px!important;color:var(--a-muted);margin-top:10px!important}
@media(max-width:1050px){.mpa-hero,.mpa-story,.mpa-heading,.mpa-install,.mpa-service{gap:35px}.mpa-hero-visual>img{height:420px}.mpa h1{font-size:44px}.mpa h2{font-size:32px}.mpa-values{gap:25px}.mpa-reference-copy{padding:18px}.mpa-reference-copy h3{font-size:19px}.mpa-jumps a{padding:15px 14px;font-size:13px}.mpa-faq{gap:40px}.mpa-proof>div{padding-inline:22px}.mpa-story img{height:360px}.mpa-service img{height:330px}}
@media(max-width:900px){.mpa-hero{grid-template-columns:1fr;gap:28px}.mpa-hero h1{max-width:680px}.mpa-hero .mpa-lead{max-width:650px}.mpa-hero-visual>img{height:360px}}
@media(max-width:700px){.mpa{padding-bottom:40px}.mpa-wrap{width:calc(100% - 32px)}.mpa-crumb{padding:22px 0}.mpa-hero{grid-template-columns:1fr;gap:28px;padding:16px 0 32px}.mpa h1{font-size:clamp(35px,9.5vw,43px)}.mpa h2{font-size:29px}.mpa-kicker{font-size:10px;margin-bottom:16px}.mpa-lead{font-size:16px;margin-top:20px!important}.mpa-hero-visual>img{height:310px}.mpa-visual-note{left:15px;right:15px;bottom:15px;padding:14px 16px;font-size:12px}.mpa-proof{grid-template-columns:1fr 1fr;padding-block:23px;gap:23px 0}.mpa-proof>div:nth-child(2){padding-left:22px}.mpa-proof .mpa-proof-copy{grid-column:1/-1;border:0;border-top:1px solid var(--a-line);padding:22px 0 0}.mpa-proof strong{font-size:31px}.mpa-proof .mpa-proof-copy strong{font-size:21px}.mpa-section{padding-top:42px}.mpa-heading{grid-template-columns:1fr;gap:22px;margin-bottom:27px}.mpa-heading p{font-size:15px}.mpa-values{grid-template-columns:1fr;gap:28px}.mpa-value{padding-top:20px}.mpa-no{margin-bottom:14px}.mpa-value h3{font-size:23px;max-width:none}.mpa-value p{font-size:15px;margin-top:12px}.mpa-story{grid-template-columns:1fr;gap:28px;padding-top:44px}.mpa-story img{height:280px}.mpa-story p{font-size:15px;margin-top:18px}.mpa-reference-row{grid-template-columns:1fr;gap:18px;margin-top:25px}.mpa-reference{display:grid;grid-template-columns:40% 60%;align-items:center}.mpa-reference-image{aspect-ratio:auto;height:180px}.mpa-reference-copy{padding:18px}.mpa-reference-copy h3{font-size:20px}.mpa-reference-copy p{font-size:9px}.mpa-reference-copy>span{font-size:12px;margin-top:12px}.mpa-cta{align-items:start;flex-direction:column;padding:28px;gap:23px;margin-top:42px}.mpa-cta h2{font-size:28px}.mpa-cta .mpa-btn{width:100%}.mpa-jumps{grid-template-columns:1fr 1fr;gap:10px}.mpa-jumps a{padding:14px;font-size:13px}.mpa-install{grid-template-columns:1fr;gap:27px;margin-top:30px;padding-top:32px}.mpa-install p{font-size:15px}.mpa-types{gap:0 16px}.mpa-types li{font-size:12px;padding-block:12px}.mpa-service{grid-template-columns:1fr;gap:25px;padding-top:44px}.mpa-service img{height:280px}.mpa-service-copy p{font-size:15px;margin-top:18px}.mpa-service-reverse .mpa-service-image,.mpa-service-reverse .mpa-service-copy{order:initial}.mpa-service-copy .mpa-text-link{margin-top:20px}.mpa-process{padding-top:32px;margin-top:44px}.mpa-faq{grid-template-columns:1fr;gap:20px;margin-top:44px;padding-top:32px}.mpa-faq summary{font-size:15px}.mpa-faq details p{font-size:14px}.mpa-actions{gap:10px;margin-top:24px}.mpa-actions .mpa-btn{padding-inline:17px;font-size:13px}}
@media(prefers-reduced-motion:reduce){.mpa img{transition:none}}
